import { useState, useRef } from 'https://esm.sh/preact/hooks';

const CheckboxField = ({ id, label, helperText, required, checked, onChange, error }) => {
  const describedBy = error ? `${id}-helper ${id}-error` : `${id}-helper`;

  return h('div', { class: 'form-field' }, [
    h('div', { class: 'checkbox-wrapper' }, [
      h('input', {
        id,
        type: 'checkbox',
        required,
        checked,
        onChange: (e) => onChange(e.target.checked),
        'aria-describedby': describedBy,
        'aria-invalid': error ? 'true' : 'false',
      }),
      h('label', { for: id }, [
        label,
        required && h('span', { class: 'required-asterisk', 'aria-hidden': 'true' }, ' *')
      ])
    ]),
    h('p', { id: `${id}-helper`, class: 'helper-text' }, helperText),
    error && h('p', { id: `${id}-error`, class: 'error-text' }, `Error: ${error}`)
  ]);
};

const App = () => {
  const [agreed, setAgreed] = useState(false);
  const [error, setError] = useState('');
  const checkboxRef = useRef(null);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!agreed) {
      setError('You must agree to the terms of use to proceed.');
      // Move focus to the checkbox as per accessibility guidelines
      document.getElementById('terms-checkbox').focus();
    } else {
      setError('');
      alert('Form submitted successfully!');
    }
  };

  return h('main', { class: 'container' }, [
    h('h1', null, 'Join our community'),
    h('form', { onSubmit: handleSubmit, novalidate: true }, [
      h(CheckboxField, {
        id: 'terms-checkbox',
        label: 'I agree to the terms of use',
        helperText: 'Please read our terms before agreeing.',
        required: true,
        checked: agreed,
        onChange: (val) => {
          setAgreed(val);
          if (val) setError('');
        },
        error: error
      }),
      h('button', { type: 'submit' }, 'Create account')
    ])
  ]);
};

render(h(App), document.getElementById('root'));
